#include "network/NativeServerStatus.h"
#include <cassert>
#include <arpa/inet.h>
#include <iostream>
int main(){int probe=socket(AF_INET,SOCK_STREAM,0);sockaddr_in a{};a.sin_family=AF_INET;a.sin_addr.s_addr=htonl(INADDR_LOOPBACK);assert(!bind(probe,(sockaddr*)&a,sizeof(a)));socklen_t n=sizeof(a);getsockname(probe,(sockaddr*)&a,&n);int port=ntohs(a.sin_port);close(probe);NativeServerStatus server;server.start(port,"test",5);assert(server.active());int fd=socket(AF_INET,SOCK_STREAM,0);assert(!connect(fd,(sockaddr*)&a,sizeof(a)));char partial=char(0x80);send(fd,&partial,1,0);std::this_thread::sleep_for(std::chrono::milliseconds(30));auto begin=std::chrono::steady_clock::now();server.stop();auto elapsed=std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now()-begin).count();assert(elapsed<1000);close(fd);assert(!server.active());std::cout<<"Slow metadata connection shutdown bounded: "<<elapsed<<"ms PASS\n";server.start(port,"again",5);assert(server.active());fd=socket(AF_INET,SOCK_STREAM,0);assert(!connect(fd,(sockaddr*)&a,sizeof(a)));char bad[5]={char(0xff),char(0xff),char(0xff),char(0xff),char(0xff)};send(fd,bad,5,0);pollfd p{fd,POLLIN,0};assert(poll(&p,1,1000)>0);char byte;assert(recv(fd,&byte,1,0)==0);close(fd);server.stop();std::cout<<"Oversized VarInt rejection and listener restart PASS\n";}
